module GoodSequenceFinder(\n    input clk, rst_n, start,\n    input [3:0] len,\n    input [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n                arr_8, arr_9, arr_10, arr_11, arr_12, arr_13, arr_14, arr_15,\n    output reg done,\n    output reg [7:0] result\n);\n    // State declarations\n    localparam [1:0] IDLE = 2'b00;\n    localparam [1:0] PROCESS = 2'b01;\n    localparam [1:0] DONE_STATE = 2'b10;\n    reg [1:0] state;\n    reg [1:0] next_state;\n    \n    // Processing registers\n    reg [3:0] index;\n    reg [7:0] overall_max;\n    reg [7:0] dp_reg [0:255];\n    reg [7:0] arr_reg [0:15];\n    reg [3:0] len_reg;\n    \n    // ROM declaration (34-bit: 4×8-bit factors + 2-bit count)\n    reg [33:0] rom [0:255];\n    \n    // Initialize ROM with factors data\n    integer rom_init_i;\n    initial begin\n        for (rom_init_i = 0; rom_init_i < 256; rom_init_i = rom_init_i + 1) begin\n            // Placeholder - real data would be precomputed\n            rom[rom_init_i] = 34'd0;\n        end\n        // Example entries (full data requires full ROM)\n        rom[1] = {8'd0,8'd0,8'd0,8'd0,2'd0};\n        rom[2] = {8'd2,8'd0,8'd0,8'd0,2'd1};\n        rom[3] = {8'd3,8'd0,8'd0,8'd0,2'd1};\n        rom[4] = {8'd2,8'd2,8'd0,8'd0,2'd2};\n    end\n    \n    // Current processing signals\n    wire [7:0] current_num = arr_reg[index];\n    wire [33:0] factors = rom[current_num];\n    wire [7:0] factor0 = factors[33:26];\n    wire [7:0] factor1 = factors[25:18];\n    wire [7:0] factor2 = factors[17:10];\n    wire [7:0] factor3 = factors[9:2];\n    wire [1:0] factor_cnt = factors[1:0];\n    \n    // DP value comparison\n    wire [7:0] dp0 = (factor_cnt > 0) ? dp_reg[factor0] : 8'd0;\n    wire [7:0] dp1 = (factor_cnt > 1) ? dp_reg[factor1] : 8'd0;\n    wire [7:0] dp2 = (factor_cnt > 2) ? dp_reg[factor2] : 8'd0;\n    wire [7:0] dp3 = (factor_cnt > 3) ? dp_reg[factor3] : 8'd0;\n    \n    wire [7:0] max1 = (dp0 > dp1) ? dp0 : dp1;\n    wire [7:0] max2 = (dp2 > dp3) ? dp2 : dp3;\n    wire [7:0] max_prev = (max1 > max2) ? max1 : max2;\n    wire [7:0] current_length = max_prev + 8'd1;\n    \n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            index <= 4'd0;\n            overall_max <= 8'd0;\n            for (integer i = 0; i < 256; i = i + 1) begin\n                dp_reg[i] <= 8'd0;\n            end\n        end else begin\n            state <= next_state;\n            \n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        arr_reg[0] <= arr_0;\n                        arr_reg[1] <= arr_1;\n                        arr_reg[2] <= arr_2;\n                        arr_reg[3] <= arr_3;\n                        arr_reg[4] <= arr_4;\n                        arr_reg[5] <= arr_5;\n                        arr_reg[6] <= arr_6;\n                        arr_reg[7] <= arr_7;\n                        arr_reg[8] <= arr_8;\n                        arr_reg[9] <= arr_9;\n                        arr_reg[10] <= arr_10;\n                        arr_reg[11] <= arr_11;\n                        arr_reg[12] <= arr_12;\n                        arr_reg[13] <= arr_13;\n                        arr_reg[14] <= arr_14;\n                        arr_reg[15] <= arr_15;\n                        len_reg <= len;\n                        index <= 4'd0;\n                        overall_max <= 8'd0;\n                        next_state <= PROCESS;\n                    end\n                end\n                \n                PROCESS: begin\n                    if (current_length > overall_max) begin\n                        overall_max <= current_length;\n                    end\n                    \n                    if (factor_cnt > 0 && current_length > dp_reg[factor0]) begin\n                        dp_reg[factor0] <= current_length;\n                    end\n                    if (factor_cnt > 1 && current_length > dp_reg[factor1]) begin\n                        dp_reg[factor1] <= current_length;\n                    end\n                    if (factor_cnt > 2 && current_length > dp_reg[factor2]) begin\n                        dp_reg[factor2] <= current_length;\n                    end\n                    if (factor_cnt > 3 && current_length > dp_reg[factor3]) begin\n                        dp_reg[factor3] <= current_length;\n                    end\n                    \n                    if (index == len_reg - 4'd1) begin\n                        next_state <= DONE_STATE;\n                    end else begin\n                        index <= index + 4'd1;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    result <= overall_max;\n                    next_state <= IDLE;\n                end\n                \n                default: begin\n                    next_state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule